import java.lang.reflect.Method; import java.net.URL; import java.net.URLClassLoader; public class InspectPosDigital { public static void main(String[] args) throws Exception { URL[] urls = { new URL("jar:file:libs/unpacked/classes.jar!/") }; URLClassLoader cl = URLClassLoader.newInstance(urls); Class<?> c = cl.loadClass("com.getnet.posdigital.PosDigital"); for (Method m : c.getDeclaredMethods()) { System.out.println(m.toString()); } } }
